cards=[]
cards.append(compact('mima_director','《密码》的国家情报局局长','这位未具姓名的局长在一座旧城长大，十一岁时听一个老人讲藏宝旧闻，少年时留下的惊惧和憧憬，逐渐变成终生的秘密欲望。他后来步步高升，成为五十出头、权势正盛的国家情报局长，表面选一角古宅作为相称的住所，实际看中了花园和可能藏在地下的财宝。他熟悉地方历史，也懂得把真实心思藏起，甚至怀念可以随意罗织罪名抓人的旧日，却知道如今不能公然这样做。与齐白合作寻宝时，他将行政资源和私人贪欲结合，以为只要打通地下便能完成童年梦想。最后亲自按下爆破掣钮，地下积水突然涌出，整片花园塌成湖泊；他跟着预先逃跑的齐白才保住性命，只能目瞪口呆地看着现场。齐白留下潜水器材离开，而他没有确证取得财宝或获得蛹中事物的能力。卡片保留其隐忍、算计和见利忘险，也明确权力要依赖具体制度与手下。叙述者推测当地可能封锁消息并假称地震，不等于已经发生的事实，更不能作为他无条件改写公众认知的技能。','《密码》爆破引起地陷后存活，寻宝失败，是否继续潜水及后续官运不明','反派','利用职位完成私藏多年的寻宝欲望，并维持自己的权势','表面讲究官阶与体面，心思深藏，熟悉所在城市的旧事','利益近在眼前时会亲自推进危险工程，突变后容易愤怒失措','把政治资源当作私人机会，但地质风险和他人的判断不会服从头衔',[ab('情报行政与隐藏意图','借职位取得场所和人手，熟悉政治察言观色与地方资料','制度和实际下属是前提；没有个人读心、精神改写或随时能抓任何人的能力'),ab('寻宝工程协作','与齐白合作使用现场探测、爆破及潜水器材','本人不是全能工程师；爆破造成灾难，装备也非无限随身资源')],[ev('073',1889,1915,'职位、罗织罪名倾向和私心'),ev('073',1922,2002,'少年藏宝执念形成'),ev('073',3035,3118,'爆破、逃命与失败后果')],profile='expert'))
cards.append(compact('feile','费勒','费勒是在马尼拉精神疗养院工作的年轻医生，看起来二十五六岁，热情地读过卫斯理的经历，却在真正碰到无法归入医学常识的病人时显得犹疑。他负责久病的郑保云，既看到病人恢复简短语言，又拘泥于此前的诊断，直到病人要见卫斯理一个月之后才设法联络。他与同事曾让三个人假扮来访者，结果都被打断肋骨；真正的卫斯理来了，他仍支吾其词，没有充分说明危险。这些不是恶意谋害，却暴露出怕承认无知、把病人的表达套入旧判断的职业缺陷。郑保云的伪装与真实异星处境超出了他的知识，随后他从门上小窗探视，与突然伸长颈子的红人面对面，受到极大惊吓，暂时陷于痴呆状态，由同事治疗。后来清醒，能够交代当时所见，说明他没有永久失去行动力，也没有因见过外星人便突然掌握外星医学。终局卡以恢复后的普通医生为主：可在具体检查中提供帮助，也能面对过去误判带来的羞愧。新场景允许他学会把未知留在记录里，但不能替原作抹掉他的迟延与不当试探。','《血统》受惊后经过一段时间清醒，向卫斯理说明所见；未获外星技术','主角','理解和照护病人，同时维护自己的专业判断','年轻热情，遇难解问题容易迟疑，熟悉常规精神医疗工作','诊断遭挑战时可能先援引旧会诊结果，受超常视觉刺激会惊恐失措','求助与承认不知道比让病人不断证明自己更有用，专业身份不能保证判断正确',[ab('常规医学观察与联络','跟踪郑保云状态，组织会诊，联络家属及卫斯理参与','不识天龙星生理；诊断和观察存在明确误判'),ab('恢复后的事件陈述','能够描述导致自己受惊的具体近距离景象','没有精神免疫，也不把受惊经历升级为超自然感知')],[ev('074',113,215,'身份、年龄及延误联络'),ev('074',316,363,'假扮者、误判及留住观察'),ev('074',1543,1550,'惊吓原因和之后清醒')],profile='expert'))
c=compact('red_visitors','寻找生命之源的红人','这批红色异星来客在地球寻找被郑天禄骗走的矿石，外形和地球人差别极大：细长的颈子托着人形头部，身体可伸缩变形，初见时足以把普通人吓坏。最先与卫斯理对话的九人不能逐一可靠区分，飞船另有众多同伴，本卡按这次共同任务的群体记录，不虚构成员姓名。他们追索郑保云、搜查旧宅，甚至把人带走，看起来像诡异的威胁，却主要急于救回依赖失物生存的同族。起初他们不愿解释生命机制，经过交谈才说明每个人只能摄取自幼对应矿石的能量，矿石被铜包住便难以定位；先进科技并没有使他们摆脱这种脆弱。卫斯理找到铜箱后，他们欢喜地表达感谢，还将箱内另一件属于天龙星的物品交还，未因被骗而一概占有敌方财物。他们后来帮助郑保云，并通过他继续致谢。卡片以寻回生命之源后的友好旅行者为终局，保留物质传送和飞船技术的条件，不把惊人的外形写成恶意恐惧法术，也不把可变身体推成免疫所有伤害。','《血统》寻回生命之源，离开并与郑保云保持联系；群体按任务成员部署，人数与飞船需具体交代',['主角','阶段性对立者'],'找回维持同族生命的矿石，并建立可交流的跨星关系','相互商议，热情但不熟悉地球人的距离感和外形恐惧','生命来源受威胁会追踪、带走相关者；确认善意后愿解释与报答','形态不同不应自动成为敌意理由，科技先进也须尊重不同生命的依赖条件',[ab('变形与狭缝通行','身体及头部能够变薄、伸展，长颈可探入狭小开口','并非随意变成其他物种或拥有所有形状的功能，未证实绝对物理免疫'),ab('飞船与物质传送','使用技术将人体分解为原子后还原，完成局部移送；飞船可星际航行','依赖完整设备和操作，不是裸身任意瞬移，星际旅程仍耗时间'),ab('思想与生命源信号感知','能感到相关思想活动和生命矿石能量，辅助交谈及追索','铜屏蔽可以阻断矿石定位；读到错误信念也可能被欺骗')],[ev('074',1543,1565,'变形、带走与搜寻'),ev('074',1658,1738,'九名交流者及友善性格'),ev('074',1797,1853,'生命源及铜屏蔽'),ev('074',1967,2002,'寻回、致谢与还物'),ev('074',3112,3118,'物质分解还原传送'),ev('074',3353,3359,'保持联系')],profile='expert',aliases=['红人（《血统》）'])
rate(c,[3,4,3,6,7,4],neg=(3,2,1),tier='凶',reason='以变形、感知及有设备的移送计分；无大规模进攻展示，生命依赖特定矿石，传送不等同概念改写。',mastery='基本掌握')
c['baseline'].update({'durability':'柔软可变身体能通过窄隙，但没有免疫穿刺、热、电或其他攻击的确证；生命还依赖对应矿石能量。','speed':'形体伸缩和局部移动极快；远程移送和星际速度来自设备。','energy':'设备可分解并还原物质用于交通，未展示任意目标的无条件歼灭。','mind':'可感知相关思想和能量，但仍会被隐瞒、错误信息和材料屏蔽困住。','stamina':'必须定期从自幼对应的一块生命矿石摄取能量，其他同成分矿石无法替代。'})
c['terms']=[{'term':'生命之源','explanation':'红人赖以定期补充生命所需能量的特定矿石；是个体与矿石的特殊生理依赖，不是宇宙生命概念的统治权。'}]
cards.append(c)
c=compact('tianlong_team','天龙星地球调查三人组','这三名来到地球的天龙星调查者外形近似人类，掌握读取思想、信号装置、隐蔽基地和强力小型武器，却把郑保云视为观察品，没有因为共同血统承认他的平等。他们要追究前次任务的背叛，也在地球准备服务母星的计划；对种族与等级的执着，使先进文明与狭窄的猜疑同时存在。三人并非一个性格：领队习惯命令和威吓，被卫斯理抓住同族相残的心理压力；一名成员在冲突中遭武器误杀，领队随后被夺来的武器击毙；最后一名原本逃离，回到基地后惶恐求生，愿操作残存设备释放白素。卫斯理放弃继续杀戮时，他暂时理解互留秘密的亲近，却仍担忧郑保云会因血统敌视而见死不救。基地与万能车受损，三人曾有的技术优势已经被打破；最后那名成员终究自尽，不能虚构他顺利融入地球的后续。本卡保留未具姓名且以共同任务为身份的群体，分列关键分歧，不把领队的残酷强加于每个人。参战若恢复他们，各按死亡前最后可行动形态，受损基地与遗失武器不能自动重置。','《血统》一人误杀、领队被杀，最后一人释放白素后自尽；参战恢复各自最后可行动形态，终局毁坏设施不随之复原','反派','完成母星任务、维护族群秩序并避免被视作背叛者','强调等级和血统，依靠先进装备观察地球，却低估人的技巧与关系','计划失控时领队强硬辩护，末员则求生、协商并畏惧回乡惩罚','共同文明不等于共同性格；对同类惩罚的恐惧可压倒现实求生利益',[ab('思想活动接收','可接收附近人的思想活动，辅以讯号装置通讯','有距离与信号条件，可遭干扰，知道念头不保证能阻止突袭'),ab('近人体格与异常力量','领队能挣脱卫斯理擒抓，重击后仍起身','仍可被能量武器杀死；技巧和观察不足，非绝对不死'),ab('任务科技','操作万能车、藏匿装置与发射精光的小盒武器','终局设备大量毁坏、武器遗失；完整历史装备须另获，不以母星科技无限补充')],[ev('074',2630,2711,'观察品态度、思想与干扰装置'),ev('074',2970,3031,'领队力量、心理破绽及死亡'),ev('074',3040,3120,'末员求生、放人及毁坏设备'),ev('074',3131,3196,'血统猜疑和前次任务信息'),ev('074',3297,3311,'末员自尽及郑的拒绝')],profile='strong')
rate(c,[5,2,1,4,5,5],neg=(2,3,2),tier='强',reason='按终局可活动身体与接收思想计分；原万能车和基地已损毁，小盒武器遗失，不叠加完整母星兵工。',mastery='基本掌握')
c['baseline'].update({'mind':'能接收相关思想，但不是无条件全知；同族惩罚与猜疑会干扰决断。','energy':'先天表现以脑活动感应为主，破坏性精光来自现已遗失的武器。','durability':'领队能承受人类近身重击继续行动，仍会被武器杀死；其他成员未证实同等战斗韧性。'})
c['adaptations'].append({'change':'按成员最后可行动形态恢复，保留死亡与失去基地的记忆','reason':'原作三人均已死亡，团体参演需要明确接口。','power_impact':'不恢复已毁万能车、基地与遗失武器，不将领队力量自动赋予末员。'})
cards.append(c)
cards.append(compact('zheng_tianlu','郑天禄','郑天禄以富豪身份在地球生活，真实出身是天龙星来客。最初来到地球的目的包含观察、实验和为未来行动准备，他娶妻生子也曾属于取得标本的安排；然而儿子长大，父子之情改变了他的取舍。他为保护郑保云杀死另外两名同伴，成为母星眼中的背叛者，这种转变有爱与勇气，也有真实的谋杀，不能简单改成三个来客共同和平归隐。他还曾骗取红人的生命之源，把重要物品和留给儿子的说明藏在厚铜箱及旧宅机关之中，使后人多年不得其解。希望儿子像自己，使他在遗留的文字中对风险和前史有所隐瞒，最终儿子选择转化，经历多年异常与身份困境。他死后尸身的异状引出早期调查，但尸体活动不等于原人格复活，更不能把它当作可随时施展的不死战斗形态。《血统》补全的终局使这位已故父亲既是保护者，也是儿子困境的设计者。参战需恢复生前最后可行动形态并保留后续被揭明的记忆，原文没有充分展示的全套天龙科技不作默认武库；被红人收回的矿石更不能继续据为己有。','生前已死；《血统》揭明保护儿子而杀同伴等旧事，生命之源归还红人；参战恢复生前最后可行动形态','重要配角','保护儿子并延续自身族属，同时摆脱母星对家庭的控制','善于隐藏身份、机关和真实用意，对儿子有强烈期待','父子关系触及任务要求时会背叛同伴，愿用致命手段保护孩子','亲情能改变任务立场，却不自动证明杀戮和替孩子安排人生都是正确',[ab('身份经营与隐匿物品','长期以地球富豪身份生活，利用铜箱屏蔽和隐藏钥匙保护资料','物品后来被发现；社会身份和秘密不能挡住全部调查'),ab('天龙星来历与知识','具有异星生理及相关任务知识，知道红人生命矿石的作用','生前战斗表现材料有限，不能直接照抄新来调查队的全部武器；已失去的矿石不列常驻')],[ev('074',1505,1533,'父亲尸体谜、留册选择与隐瞒'),ev('074',1797,1853,'生命矿石与铜箱'),ev('074',3190,3200,'护子而谋杀同伴的揭示'),ev('074',3320,3336,'父子关系与儿子的最终认识')],profile='expert'))
cards[-1]['adaptations'].append({'change':'恢复生前最后可行动形态并保留被揭明的终局记忆','reason':'原作死亡及尸体异状没有证实本人人格复活。','power_impact':'只恢复行动，不恢复矿石、富豪产业、全部原乡设备。'})
cards.append(compact('chen_san','陈三','陈三是郑家旧宅的总管，主人离世或病倒之后仍维持宅内事务，和来自故乡的仆人一同照看空置的院落。他在仆佣中近于半个主人，忠心而讲究旧规矩，知道郑天禄书房曾经不许闲人接近。连续几夜的声响与怪影使人以为闹鬼，他既怕，又感到不能置之不理，白天带着五七个拿棍的壮仆进去查看，夜里还从门缝窥视。他用香烛纸钱、请僧念经等自己熟悉的办法应对，结果没有解决问题；等知道卫斯理在附近，便赶去求助。讲述时他噜苏而紧张，会把听来的声音和自己想到的鬼魂联系起来，受责备后又委屈得不知如何解释，不能把他的口述当成无误的外星学报告。他虽害怕跟着守夜，却仍送来满篮饭食和好酒，让愿意调查的人继续做事。终局卡以郑家事务的守护者和跨案见证人为主，没有超自然驱邪本领或强大战斗力。新场景中他的价值来自熟悉环境、照料日常、动员可信的人以及肯向懂行者求助，也保留忠诚与恐惧互相拉扯的真实反应。','《血统》继续守护郑家旧宅，协助卫斯理调查；未获红人或天龙星能力','重要配角','维持郑家日常安全，向主家和留守仆人尽责','熟悉宅院与旧规矩，讲述细碎，会先用乡俗理解异常','害怕仍会组织白天查验并求助，但不愿独自迎面冒险','恐惧中的传闻要与亲见分开，求助不等于放弃照料与责任',[ab('宅院管理与地方关系','熟悉曲折院落，安排仆人、日常打扫、食物及接待','限于实际管理的人手；没有无限忠仆或普遍行政权'),ab('现场见证与组织查看','将多人经历串联，组织白天查验，把异状交给调查者','误判为鬼，驱邪办法无效；不把听来的声音当作本人确见')],[ev('074',909,946,'总管地位、求助与宅院知识'),ev('074',997,1020,'组织、错误办法与责任感'),ev('074',1046,1072,'恐惧及饭食协助')],profile='ordinary'))
save(cards)
